const raw = $('Extract Story Log').first().json;
const log = raw.data ?? raw;
const used = log.used || [];
if (!used.length) throw new Error('No stories in story-log.json. Run Module 4 first.');
const id = used[used.length - 1].id;
return [{ json: { story_id: id, scenes_path: `/data/output/scenes/${id}.json`, audio_manifest_path: `/data/output/audio/${id}_audio.json` } }];

const cfgRaw = $('Extract Subtitle Config').first().json;
const cfg = cfgRaw.data ?? cfgRaw;
const scRaw = $('Extract Scenes').first().json;
const sc = scRaw.data ?? scRaw;
const amRaw = $('Extract Audio Manifest').first().json;
const am = amRaw.data ?? amRaw;

const maxChars = cfg.max_chars_per_cue || 42;
const maxWords = cfg.max_words_per_cue || 9;

const durByScene = {};
for (const c of (am.clips || [])) durByScene[c.scene_number] = c.duration_seconds;

function chunk(text) {
  const sentences = text.match(/[^.!?]+[.!?]*\s*/g) || [text];
  const cues = [];
  for (let s of sentences) {
    s = s.trim();
    if (!s) continue;
    const words = s.split(/\s+/);
    if (words.length <= maxWords && s.length <= maxChars) { cues.push(s); continue; }
    let cur = [], curLen = 0;
    for (const w of words) {
      const addLen = curLen + (cur.length ? 1 : 0) + w.length;
      if (cur.length && (cur.length >= maxWords || addLen > maxChars)) {
        cues.push(cur.join(' ')); cur = [w]; curLen = w.length;
      } else { cur.push(w); curLen = addLen; }
    }
    if (cur.length) cues.push(cur.join(' '));
  }
  return cues.length ? cues : [text];
}

const p = (n, l=2) => String(n).padStart(l, '0');
function fmtSrt(t) { const ms = Math.round((t - Math.floor(t)) * 1000); let s = Math.floor(t); const h = Math.floor(s/3600); s -= h*3600; const m = Math.floor(s/60); s -= m*60; return `${p(h)}:${p(m)}:${p(s)},${p(ms,3)}`; }
function fmtAss(t) { const cs = Math.round((t - Math.floor(t)) * 100); let s = Math.floor(t); const h = Math.floor(s/3600); s -= h*3600; const m = Math.floor(s/60); s -= m*60; return `${h}:${p(m)}:${p(s)}.${p(cs)}`; }

const cues = [];
let cursor = 0;
for (const scene of sc.scenes) {
  const dur = durByScene[scene.scene_number] || scene.duration_seconds || 2;
  const parts = chunk(scene.narration);
  const wc = parts.map(x => x.split(/\s+/).length);
  const totalW = wc.reduce((a, b) => a + b, 0) || 1;
  let local = cursor;
  parts.forEach((text, i) => {
    const cueDur = (wc[i] / totalW) * dur;
    cues.push({ start: local, end: local + cueDur, text });
    local += cueDur;
  });
  cursor += dur;
}

let srt = '';
cues.forEach((c, i) => { srt += `${i+1}\n${fmtSrt(c.start)} --> ${fmtSrt(c.end)}\n${c.text}\n\n`; });

const st = cfg.ass_style || {};
const font = st.font || 'DejaVu Sans';
const size = st.font_size || 54;
const primary = st.primary_color || '&H00FFFFFF';
const outlineC = st.outline_color || '&H00000000';
const outline = st.outline ?? 4;
const shadow = st.shadow ?? 1;
const align = st.alignment ?? 2;
const marginV = st.margin_v ?? 70;
const assHeader = `[Script Info]\nScriptType: v4.00+\nPlayResX: 1920\nPlayResY: 1080\nWrapStyle: 0\nScaledBorderAndShadow: yes\n\n[V4+ Styles]\nFormat: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\nStyle: Default,${font},${size},${primary},&H000000FF,${outlineC},&H64000000,-1,0,0,0,100,100,0,0,1,${outline},${shadow},${align},60,60,${marginV},1\n\n[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n`;
let ass = assHeader;
cues.forEach(c => { const t = c.text.replace(/\r?\n/g, ' ').trim(); ass += `Dialogue: 0,${fmtAss(c.start)},${fmtAss(c.end)},Default,,0,0,0,,${t}\n`; });

return [{ json: {
  story_id: sc.story_id,
  srt_path: `/data/output/subtitles/${sc.story_id}.srt`,
  ass_path: `/data/output/subtitles/${sc.story_id}.ass`,
  srtB64: Buffer.from(srt, 'utf8').toString('base64'),
  assB64: Buffer.from(ass, 'utf8').toString('base64'),
  cue_count: cues.length,
  total_duration_seconds: Math.round(cursor * 100) / 100
} }];
